CREATE OR REPLACE FUNCTION public.add_signature_revision(p_signature_id uuid, p_file_url text DEFAULT NULL::text, p_file_name text DEFAULT NULL::text, p_file_mime text DEFAULT NULL::text, p_document_html text DEFAULT NULL::text, p_change_summary text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid; v_user_name text; v_sig RECORD; v_next_version int; v_rev_id uuid; v_is_admin boolean;
BEGIN
  v_user := auth.uid();
  IF v_user IS NULL THEN RAISE EXCEPTION 'Auth required'; END IF;
  SELECT * INTO v_sig FROM document_signatures WHERE id = p_signature_id;
  IF v_sig IS NULL THEN RAISE EXCEPTION 'Signature not found'; END IF;
  v_is_admin := has_role('admin'::app_role, v_user);
  IF v_user <> v_sig.sender_user_id AND NOT v_is_admin
     AND v_user <> COALESCE(v_sig.recipient_user_id, '00000000-0000-0000-0000-000000000000'::uuid) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  SELECT COALESCE(full_name, email, 'Пользователь') INTO v_user_name FROM profiles WHERE user_id = v_user LIMIT 1;
  IF v_user_name IS NULL AND v_is_admin THEN v_user_name := 'Администратор Синтагма'; END IF;
  SELECT COALESCE(MAX(version),0)+1 INTO v_next_version FROM signature_revisions WHERE signature_id = p_signature_id;

  INSERT INTO signature_revisions (
    signature_id, version, document_html, file_url, file_name, file_mime,
    created_by, created_by_name, change_summary
  ) VALUES (
    p_signature_id, v_next_version, p_document_html, p_file_url, p_file_name, p_file_mime,
    v_user, v_user_name, p_change_summary
  ) RETURNING id INTO v_rev_id;

  UPDATE document_signatures
  SET current_revision_id = v_rev_id, status = 'in_review', updated_at = now()
  WHERE id = p_signature_id;

  IF v_user <> v_sig.sender_user_id THEN
    INSERT INTO org_notifications (organization_id, user_id, type, title, message, related_id)
    VALUES (
      v_sig.organization_id, v_sig.sender_user_id, 'signature',
      'Новая версия документа от ' || v_user_name,
      v_sig.document_title || COALESCE(' — ' || p_change_summary, ''),
      p_signature_id
    );
  END IF;
  RETURN v_rev_id;
END; $function$

CREATE OR REPLACE FUNCTION public.create_external_contract_signature(p_file_url text, p_file_name text, p_file_mime text, p_document_title text, p_admin_email text, p_admin_name text DEFAULT 'Администратор Синтагма'::text, p_summary text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org_id uuid; v_sender uuid; v_sender_name text; v_sig_id uuid; v_rev_id uuid;
BEGIN
  v_sender := auth.uid();
  IF v_sender IS NULL THEN RAISE EXCEPTION 'Auth required'; END IF;
  v_org_id := current_organization_id();
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'No organization'; END IF;
  SELECT COALESCE(full_name, email, 'Организация') INTO v_sender_name FROM profiles WHERE user_id = v_sender LIMIT 1;

  INSERT INTO document_signatures (
    organization_id, sender_user_id, sender_name,
    document_type, document_title,
    recipient_type, recipient_email, recipient_name,
    status, mode, requires_bilateral
  ) VALUES (
    v_org_id, v_sender, v_sender_name,
    'external_upload', p_document_title,
    'admin_sintagma', p_admin_email, p_admin_name,
    'in_review', 'review', true
  ) RETURNING id INTO v_sig_id;

  INSERT INTO signature_revisions (
    signature_id, version, document_html, document_hash,
    file_url, file_name, file_mime,
    created_by, created_by_name, change_summary
  ) VALUES (
    v_sig_id, 1, NULL, NULL,
    p_file_url, p_file_name, p_file_mime,
    v_sender, v_sender_name, COALESCE(p_summary, 'Первоначальная версия')
  ) RETURNING id INTO v_rev_id;

  UPDATE document_signatures SET current_revision_id = v_rev_id WHERE id = v_sig_id;
  RETURN v_sig_id;
END; $function$

CREATE OR REPLACE FUNCTION public.create_external_contract_signature(p_file_url text, p_file_name text, p_file_mime text, p_document_title text, p_admin_email text, p_admin_name text DEFAULT 'Администратор Синтагма'::text, p_summary text DEFAULT NULL::text, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
  v_sender uuid;
  v_sender_name text;
  v_sig_id uuid;
  v_rev_id uuid;
  v_is_member boolean;
  v_is_admin boolean;
BEGIN
  v_sender := auth.uid();
  IF v_sender IS NULL THEN RAISE EXCEPTION 'Auth required'; END IF;

  v_is_admin := has_role('admin'::app_role, v_sender);

  -- 1) If org id passed: admin can use any org; non-admin must be a member
  IF p_organization_id IS NOT NULL THEN
    IF v_is_admin THEN
      v_org_id := p_organization_id;
    ELSE
      SELECT EXISTS(
        SELECT 1 FROM public.profiles WHERE user_id = v_sender AND organization_id = p_organization_id
        UNION ALL
        SELECT 1 FROM public.org_staff WHERE user_id = v_sender AND organization_id = p_organization_id
      ) INTO v_is_member;
      IF v_is_member THEN
        v_org_id := p_organization_id;
      END IF;
    END IF;
  END IF;

  -- 2) Fallback: derive from session
  IF v_org_id IS NULL THEN
    v_org_id := current_organization_id();
  END IF;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization: пользователь не привязан к организации (profiles/org_staff)';
  END IF;

  -- Resolve sender name
  SELECT COALESCE(full_name, email, 'Организация') INTO v_sender_name FROM profiles WHERE user_id = v_sender LIMIT 1;
  IF v_sender_name IS NULL THEN
    SELECT COALESCE(display_name, 'Организация') INTO v_sender_name FROM org_staff WHERE user_id = v_sender LIMIT 1;
  END IF;
  IF v_sender_name IS NULL AND v_is_admin THEN v_sender_name := 'Администратор Синтагма'; END IF;

  INSERT INTO document_signatures (
    organization_id, sender_user_id, sender_name,
    document_type, document_title,
    recipient_type, recipient_email, recipient_name,
    status, mode, requires_bilateral
  ) VALUES (
    v_org_id, v_sender, COALESCE(v_sender_name, 'Организация'),
    'external_upload', p_document_title,
    'admin_sintagma', p_admin_email, p_admin_name,
    'in_review', 'review', true
  ) RETURNING id INTO v_sig_id;

  INSERT INTO signature_revisions (
    signature_id, version, document_html, document_hash,
    file_url, file_name, file_mime,
    created_by, created_by_name, change_summary
  ) VALUES (
    v_sig_id, 1, NULL, NULL,
    p_file_url, p_file_name, p_file_mime,
    v_sender, COALESCE(v_sender_name, 'Организация'), COALESCE(p_summary, 'Первоначальная версия')
  ) RETURNING id INTO v_rev_id;

  UPDATE document_signatures SET current_revision_id = v_rev_id WHERE id = v_sig_id;
  RETURN v_sig_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.uc_document_storage_scope(p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_org uuid;v_user uuid;v_enrollment uuid;v_group uuid;
BEGIN
 IF p_bucket NOT IN('student-documents','company-documents','billing-documents','org-documents','incoming-documents','program-documents','frdo-documents','signed-documents','external-contracts') THEN RETURN true; END IF;
 IF auth.uid() IS NULL OR NOT public.account_deletion_access_allowed() THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.org_staff s WHERE s.user_id=auth.uid() AND s.role='teacher')
 OR public.has_role(auth.uid(),'admin'::public.app_role) THEN RETURN true; END IF;
 IF p_bucket='student-documents' THEN
  IF split_part(p_name,'/',1)='students' THEN
   v_enrollment:=public.storage_try_uuid(split_part(p_name,'/',2));
   SELECT c.organization_id,e.user_id INTO v_org,v_user FROM public.enrollments e JOIN public.courses c ON c.id=e.course_id WHERE e.id=v_enrollment;
   RETURN v_user=auth.uid() OR (v_org IS NOT NULL AND (NOT public.uc_document_teacher_limited(v_org) OR public.uc_document_scope_allowed(v_org,NULL,v_enrollment)));
  END IF;
  IF split_part(p_name,'/',1) IN('avatars','support') THEN
   v_user:=public.storage_try_uuid(split_part(split_part(p_name,'/',2),'.',1));
  ELSE v_user:=public.storage_try_uuid(split_part(p_name,'/',1)); END IF;
  IF v_user=auth.uid() THEN RETURN true; END IF;
  SELECT organization_id INTO v_org FROM public.profiles WHERE user_id=v_user;
  RETURN v_org IS NOT NULL AND public.uc_document_student_scope_allowed(v_org,v_user);
 ELSIF p_bucket='company-documents' THEN
  SELECT c.organization_id,c.user_id INTO v_org,v_user FROM public.companies c WHERE c.id=public.storage_try_uuid(split_part(p_name,'/',1));
  RETURN v_user=auth.uid() OR (v_org IS NOT NULL AND NOT public.uc_document_teacher_limited(v_org));
 ELSIF p_bucket IN('signed-documents','external-contracts') AND EXISTS(
  SELECT 1 FROM public.document_signatures s WHERE public.uc_document_signature_read_scope(s.id) AND s.organization_id::text=split_part(p_name,'/',1)
   AND (s.signed_document_path=p_name AND p_bucket='signed-documents'
     OR s.handwritten_scan_path=p_name AND p_bucket='external-contracts'
     OR s.signed_source_bucket=p_bucket AND s.signed_source_path=p_name
     OR p_bucket='external-contracts' AND EXISTS(SELECT 1 FROM public.signature_revisions r WHERE r.signature_id=s.id
       AND (r.file_url=p_name OR right(split_part(r.file_url,'?',1),length('/external-contracts/'||p_name))='/external-contracts/'||p_name))))
 THEN RETURN true;
 END IF;
 IF p_bucket='external-contracts' AND EXISTS(SELECT 1 FROM public.document_signatures s
  WHERE s.recipient_user_id=auth.uid() AND s.deleted_at IS NULL AND s.expires_at>now()
   AND s.status IN('sent','viewed','in_review') AND
   left(p_name,length(s.organization_id::text||'/signed-scans/'||s.id::text||'-'))=s.organization_id::text||'/signed-scans/'||s.id::text||'-')
 THEN RETURN true; END IF;
 IF split_part(p_name,'/',1)='organizations' THEN
  v_org:=public.storage_try_uuid(split_part(p_name,'/',2));
  IF p_bucket='billing-documents' AND split_part(p_name,'/',3)='group-documents' THEN
   v_group:=public.storage_try_uuid(split_part(p_name,'/',4));
   RETURN public.uc_document_scope_allowed(v_org,v_group,NULL) AND v_group IS NOT NULL AND split_part(p_name,'/',5)<>'';
  END IF;
 ELSE v_org:=public.storage_try_uuid(split_part(p_name,'/',1)); END IF;
 IF v_org IS NULL THEN RETURN false; END IF;
 IF NOT public.uc_document_teacher_limited(v_org) THEN RETURN true; END IF;
 IF p_bucket='billing-documents' THEN
  IF split_part(p_name,'/',2)='contracts' AND split_part(p_name,'/',4)<>'' AND split_part(p_name,'/',5)<>'' THEN
   v_group:=public.storage_try_uuid(split_part(p_name,'/',3));
   RETURN v_group IS NOT NULL AND public.uc_document_scope_allowed(v_org,v_group,NULL);
  END IF;
  RETURN EXISTS(SELECT 1 FROM public.group_documents d WHERE d.organization_id=v_org AND d.file_path=p_name
   AND public.uc_document_record_scope(d.organization_id,d.group_id,NULL,d.student_user_id,NULL))
   OR EXISTS(SELECT 1 FROM public.org_contracts d WHERE d.organization_id=v_org AND p_name IN(d.file_path,d.docx_path,d.pdf_path)
   AND public.uc_document_contract_scope(d.organization_id,d.student_group_id,d.student_user_id,d.company_id,d.students));
 END IF;
 RETURN false;
END;$function$

CREATE OR REPLACE FUNCTION public.uc_guard_signature_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.document_signatures%ROWTYPE; v_id uuid;
BEGIN
 v_id:=CASE WHEN TG_OP='DELETE' THEN OLD.signature_id ELSE NEW.signature_id END;
 SELECT * INTO s FROM public.document_signatures WHERE id=v_id FOR UPDATE;
 IF NOT FOUND OR s.deleted_at IS NOT NULL OR s.status IN ('signed','revoked','rejected','expired') OR s.signed_at IS NOT NULL THEN
  RAISE EXCEPTION 'Signature revision is closed' USING ERRCODE='42501'; END IF;
 IF auth.role()<>'service_role' AND NOT public.uc_signature_actor_allowed(v_id,true,true) THEN
  RAISE EXCEPTION 'Revision permission denied' USING ERRCODE='42501'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Signature revision history cannot be deleted' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND (OLD.document_html IS NOT NULL AND OLD.document_html<>'') THEN
  RAISE EXCEPTION 'Create a new revision instead of overwriting history' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['document_html','document_hash']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['document_html','document_hash']) THEN
  RAISE EXCEPTION 'Revision provenance is immutable' USING ERRCODE='42501'; END IF;
 IF NEW.document_html IS NOT NULL THEN NEW.document_hash:=encode(sha256(convert_to(NEW.document_html,'UTF8')),'hex'); END IF;
 RETURN NEW;
END;$function$
